// ==UserScript==
// @name         SenpaDelta on delt.io
// @namespace    shrkawy.senpadelta
// @version      1.0.2
// @description  Runs the uploaded SenpaDelta/ONYX client directly on delt.io so the page hostname remains delt.io.
// @author       Local conversion
// @match        https://delt.io/*
// @match        https://www.delt.io/*
// @match        http://delt.io/*
// @match        http://www.delt.io/*
// @run-at       document-start
// @noframes
// @grant        none
// ==/UserScript==

(function () {
  'use strict';

  // Keep the actual browser origin/hostname as delt.io; replace only the document contents.
  try { window.stop(); } catch (_) {}

  const shell = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="minimal-ui,width=device-width,minimum-scale=1,initial-scale=1,maximum-scale=1,user-scalable=no">
<meta name="theme-color" content="#00ff00">
<title>SenpaDelta — delt.io</title>
<link href="https://fonts.googleapis.com/css?family=Rajdhani:400,500,600|Rubik|Ubuntu:400,500|Roboto:300,400,500,700" rel="stylesheet">
<link rel="stylesheet" href="https://use.fontawesome.com/releases/v5.11.1/css/all.css" crossorigin="anonymous">
<style>
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#111}
#tm-loader{position:fixed;inset:0;z-index:2147483647;display:flex;align-items:center;justify-content:center;flex-direction:column;background:#0d0f13;color:#fff;font:600 15px/1.4 Segoe UI,system-ui,sans-serif}
#tm-loader small{margin-top:8px;color:#9aa6b8;font-weight:400}
#tm-loader.err{align-items:flex-start;justify-content:flex-start;padding:28px;box-sizing:border-box;overflow:auto;white-space:pre-wrap;color:#ffb4b4}
#captcha-overlay{align-items:center;background-color:rgba(0,0,0,.55);display:flex;height:100%;justify-content:center;left:0;position:fixed;top:0;visibility:hidden;width:100%;z-index:10000}
#captcha-overlay.visible,#captcha-overlay[style*="visible"]{visibility:visible!important}
#cf-turnstile,.cf-turnstile{background:#1a1a1a;border-radius:8px;padding:16px;box-shadow:0 8px 32px rgba(0,0,0,.5)}
</style>
</head>
<body>
<div id="tm-loader">Loading SenpaDelta on delt.io<small>Origin: <span id="tm-origin"></span></small></div>
<svg height="0" width="0"><filter id="hue-rotate"><feColorMatrix in="SourceGraphic" id="matrix" type="matrix" color-interpolation-filters="sRGB"/></filter></svg>
<canvas id="screen" class="screen"></canvas>
<div id="ui-root"></div>
</body>
</html>`;

  try {
    document.open();
    document.write(shell);
    document.close();
  } catch (e) {
    console.error('[SenpaDelta-TM] Could not replace document', e);
    return;
  }

  const originEl = document.getElementById('tm-origin');
  if (originEl) originEl.textContent = location.origin;

  const RES = {
    "restore": "",
    "auth": "",
    "main": "",
    "vendors": "",
    "engine": "",
    "css": "",
    "wasm": "",
    "discord": "",
    "facebook": "",
    "forum": "",
    "logo": "",
    "noskin": "",
    "twitter": "",
    "youtube": "",
    "foodbg": "",
    "hiddenx": "",
    "rainbow": "",
    "shield": ""
  };

  const MIME = {
    wasm:'application/wasm', discord:'image/svg+xml', facebook:'image/png', forum:'image/png', logo:'image/png',
    noskin:'image/png', twitter:'image/png', youtube:'image/png', foodbg:'image/png', hiddenx:'image/png',
    rainbow:'image/png', shield:'image/png'
  };

  function bytesFromB64(b64) {
    const bin = atob(b64);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }

  async function unpackBytes(key) {
    const compressed = bytesFromB64(RES[key]);
    if (typeof DecompressionStream !== 'function') {
      throw new Error('This browser does not support DecompressionStream. Use current Chrome/Edge.');
    }
    const ds = new DecompressionStream('gzip');
    const stream = new Blob([compressed]).stream().pipeThrough(ds);
    return new Uint8Array(await new Response(stream).arrayBuffer());
  }

  async function unpackText(key) {
    return new TextDecoder().decode(await unpackBytes(key));
  }

  function blobUrl(bytes, type) {
    return URL.createObjectURL(new Blob([bytes], {type}));
  }

  function replaceAllLiteral(text, from, to) {
    return text.split(from).join(to);
  }

  function patchCode(text, urls, trackerUrl) {
    const replacements = {
      'bundle.wasm': urls.wasm,
      'build/resources/img/rainbow.png': urls.rainbow,
      'build/resources/img/shield.png': urls.shield,
      './img/discord.svg': urls.discord,
      './img/facebook.png': urls.facebook,
      './img/forum.png': urls.forum,
      './img/logo-med.png': urls.logo,
      './img/no-skin.png': urls.noskin,
      './img/twitter.png': urls.twitter,
      './img/youtube.png': urls.youtube,
      './img/food-bg.png': urls.foodbg,
      './img/hiddenx.png': urls.hiddenx,
      '/api/tracker': trackerUrl
    };
    for (const [from, to] of Object.entries(replacements)) text = replaceAllLiteral(text, from, to);
    return text;
  }

  function runGlobal(code, label) {
    // Tampermonkey @grant none executes with page globals; sourceURL keeps console errors readable.
    try {
      (0, eval)(code + '\n//# sourceURL=senpadelta-tm-' + label + '.js');
    } catch (e) {
      console.error('[SenpaDelta-TM] script failed:', label, e);
      const msg = e && e.message ? e.message : String(e);
      throw new Error(label + ': ' + msg, { cause: e });
    }
  }

  function installCell2Nickname() {
    const P = (k) => 'cell2Nick:' + k;
    let last = '';
    const f = () => {
      const i = document.querySelector('#primary-inputs input#name');
      if (!i || i.dataset.cell2) return;
      i.dataset.cell2 = '1';
      const j = i.cloneNode(true);
      j.placeholder = 'Cell 2 nickname';
      j.style.marginLeft = '6px';
      const norm = (s) => (typeof s === 'string' && s.length ? s : '');
      const apply = () => queueMicrotask(() => {
        const a = norm(i.value);
        if (!a || a === last) return;
        last = a;
        const b = norm(localStorage.getItem(P(a)) || a + '-2');
        j.value = b;
        window.__connNicks = [a, b];
      });
      j.oninput = () => {
        const a = norm(i.value), b = norm(j.value);
        if (!a || !b) return;
        localStorage.setItem(P(a), b);
        window.__connNicks = [a, b];
      };
      i.parentNode.appendChild(j);
      setInterval(apply, 150);
      apply();
    };
    new MutationObserver(f).observe(document.body, {childList:true, subtree:true});

    const st = document.createElement('style');
    st.textContent = '#primary-inputs{display:flex;gap:6px;overflow:visible}#primary-inputs input#tag{flex:0 0 auto}#primary-inputs input#name,#primary-inputs input[data-cell2]{flex:1 1 0;min-width:0;max-width:calc(50% - 3px)}';
    document.head.appendChild(st);
  }

  async function waitForShell() {
    const started = Date.now();
    while (Date.now() - started < 5000) {
      if (document.head && document.body && document.getElementById('ui-root') && document.getElementById('screen')) {
        // Give the HTML parser one extra task before React mounts.
        await new Promise(resolve => setTimeout(resolve, 25));
        if (document.getElementById('ui-root') && document.getElementById('screen')) return;
      }
      await new Promise(resolve => setTimeout(resolve, 10));
    }

    // Hard fallback: React 17 error #200 is thrown when the target container is missing/not an element.
    if (!document.documentElement) document.appendChild(document.createElement('html'));
    if (!document.head) document.documentElement.insertBefore(document.createElement('head'), document.documentElement.firstChild);
    if (!document.body) document.documentElement.appendChild(document.createElement('body'));
    if (!document.getElementById('screen')) {
      const canvas = document.createElement('canvas');
      canvas.id = 'screen';
      canvas.className = 'screen';
      document.body.appendChild(canvas);
    }
    if (!document.getElementById('ui-root')) {
      const root = document.createElement('div');
      root.id = 'ui-root';
      document.body.appendChild(root);
    }
  }

  async function boot() {
    try {
      await waitForShell();
      const reactRoot = document.getElementById('ui-root');
      if (!reactRoot || reactRoot.nodeType !== 1) {
        throw new Error('ui-root is missing before React boot');
      }
      console.log('[SenpaDelta-TM] shell ready', {readyState: document.readyState, root: reactRoot, body: !!document.body});

      // Decode binary assets first and turn them into same-document blob URLs.
      const binaryKeys = Object.keys(MIME);
      const urls = {};
      for (const key of binaryKeys) urls[key] = blobUrl(await unpackBytes(key), MIME[key]);

      // In-memory replacement for the Vercel /api/tracker function.
      const tracker = [{
        id:0,num_players:0,max_players:200,num_spectators:0,count:'EU - ONYX',
        host:'eu.senpa.io:2001',name:'EU - ONYX',region:'EU',mode:'ffa',mode_name:'FFA',version:'ONYX'
      }];
      const trackerUrl = URL.createObjectURL(new Blob([JSON.stringify(tracker)], {type:'application/json'}));

      // CSS from the uploaded build.
      let css = await unpackText('css');
      css = replaceAllLiteral(css, './img/food-bg.png', urls.foodbg);
      const style = document.createElement('style');
      style.id = 'senpadelta-main-css';
      style.textContent = css;
      document.head.appendChild(style);

      // Decode + patch the exact uploaded scripts.
      let restore = await unpackText('restore');
      let auth = await unpackText('auth');
      let main = patchCode(await unpackText('main'), urls, trackerUrl);
      // React 17 render target: force a real element even if document.write parsing races at document-start.
      const renderTargetExpr = 'document[_0x40c5a9(0x9f9)](_0x40c5a9(0x28d))';
      if (main.includes(renderTargetExpr)) {
        main = main.split(renderTargetExpr).join('(document.getElementById("ui-root") || (function(){var r=document.createElement("div");r.id="ui-root";document.body.appendChild(r);return r;})())');
      }
      let vendors = patchCode(await unpackText('vendors'), urls, trackerUrl);
      let engine = patchCode(await unpackText('engine'), urls, trackerUrl);

      runGlobal(restore, 'restore-server');
      runGlobal(auth, 'onyx-senpa-auth');
      runGlobal(main, 'main-ui');
      runGlobal(vendors, 'vendors');
      installCell2Nickname();
      runGlobal(engine, 'senpaobs');

      const loader = document.getElementById('tm-loader');
      if (loader) loader.remove();
      console.log('[SenpaDelta-TM] Booted on', location.href, 'hostname=', location.hostname);
    } catch (err) {
      console.error('[SenpaDelta-TM] BOOT FAILED', err);
      const loader = document.getElementById('tm-loader');
      if (loader) {
        loader.classList.add('err');
        loader.textContent = 'SenpaDelta Tampermonkey boot failed\\n\\n' + (err && (err.stack || err.message) || String(err));
      }
    }
  }

  boot();
})();
